import { Button } from '@astryxdesign/core';

export default function App() {
  return <Button variant="primary">Hello Astryx</Button>;
}

import { GBrain } from 'gbrain';

const brain = new GBrain();
await brain.remember({
  fact: 'Project X uses React 19 and Vite',
  source: 'README.md'
});
const context = await brain.query('What version of React does Project X use?');

import { renderVideo } from 'hyperframes';

await renderVideo({
  html: '<h1>Hello Agent Video</h1>',
  output: 'output.mp4'
});

use artcraft::prelude::*;

fn main() {
    let mut engine = ArtEngine::new();
    engine.load_project("project.art");
    engine.run_render_pipeline();
}

